zones = {1: "standoffs", 2: "board screws", 3: "drive screws",
         4: "PSU screws", 5: "fan screws", 6: "spares"}
print("Hex-Zone tray: 6 isolated magnetic pockets")
for z, role in zones.items():
    print(f"  zone {z}: {role}")

staged = {1: 9, 2: 9, 3: 4, 4: 4, 5: 8, 6: 3}
end = {1: 0, 2: 1, 3: 0, 4: 0, 5: 0, 6: 3}
issues = {z: end[z] for z in end if z != 6 and end[z] > 0}
print("End-of-build zone check:", "PASS - all zones clear" if not issues else f"FAIL zones {issues}")

card = {1: "9x M3 standoffs", 2: "9x M3 board screws", 3: "4x M2 NVMe",
        4: "4x #6-32 PSU", 5: "8x fan screws", 6: "2x jumpers + spare"}
print("Zone-map card for today's build:")
for z in range(1, 7):
    print(f"  zone {z}: {card[z]}")
print("Card filed after build -> reusable build log.")

tuning = {1: "strong", 2: "gentle (shimmed)", 3: "gentle (shimmed)",
          4: "strong", 5: "strong", 6: "gentle (shimmed)"}
for z in range(1, 7):
    print(f"  zone {z}: {tuning[z]}")
print("Rule: tiny hardware -> gentle; chunky hardware -> strong.")
